    /// The consumer's state, for the release.
    st: &'c mut ConsumerState,
    /// The slot body, viewed as the message type. Raw on purpose,
    /// see the SPSC `ReadSlot`.
    msg: *const T,
    /// Owns the `&'c mut` borrow of the consumer.
    _slot: PhantomData<&'c T>,
}

