            for &depth in &DEPTHS {
                if depth < flavor.min_depth {
                    row.push_str(&format!(" {:>7} |", "-"));
                    continue;
                }
                let secs = match placement {
                    SweepPlacement::OneT => (flavor.one_t)(depth),
                    SweepPlacement::TwoT(pin) => (flavor.two_t)(*pin, depth),
                };
                row.push_str(&format!(" {:>7.1} |", secs * 1e9 / COUNT as f64));
            }
            println!("{row}");
        }
    }
}

